20	package ca.uhn.fhir.jpa.migrate.taskdef;
21	
22	import ca.uhn.fhir.i18n.Msg;
23	import ca.uhn.fhir.jpa.migrate.DriverTypeEnum;
24	
25	/**
26	 * Helper to extract database information about supported migrations.
27	 */
28	public class MetadataSource {
29	
30		/**
31		 * Does this database support index operations without write-locking the table?
32		 */
33		public boolean isOnlineIndexSupported(DriverTypeEnum.ConnectionProperties theConnectionProperties) {
34	
35			switch (theConnectionProperties.getDriverType()) {
36				case POSTGRES_9_4:
37				case COCKROACHDB_21_1:
38					return true;
39				case MSSQL_2012:
40					String mssqlEdition = getEdition(theConnectionProperties);
41					return mssqlEdition.startsWith("Enterprise");
42				case ORACLE_12C:
43					String oracleEdition = getEdition(theConnectionProperties);
44					return oracleEdition.contains("Enterprise");
45				default:
46					return false;
47			}
48		}
49	
50		/**
51		 * Get the MS Sql Server or Oracle Server edition.  Other databases are not supported yet.
52		 *
53		 * @param theConnectionProperties the database to inspect
54		 * @return the edition string (e.g. Standard, Enterprise, Developer, etc.)
55		 */
56		private String getEdition(DriverTypeEnum.ConnectionProperties theConnectionProperties) {
57			final String result;
58			if (theConnectionProperties.getDriverType() == DriverTypeEnum.MSSQL_2012) {
59				result = theConnectionProperties
60						.newJdbcTemplate()
61						.queryForObject("SELECT SERVERPROPERTY ('edition')", String.class);
62			} else if (theConnectionProperties.getDriverType() == DriverTypeEnum.ORACLE_12C) {
63				result = theConnectionProperties
64						.newJdbcTemplate()
65						.queryForObject("SELECT BANNER FROM v$version WHERE banner LIKE 'Oracle%'", String.class);
66			} else {
67				throw new UnsupportedOperationException(Msg.code(2084) + "We only know about MSSQL editions.");
68			}
69			return result;
70		}
71	}
