	/**
	 * Wrap a SQL Server create-index statement so it attempts an ONLINE (non-locking) build first, and falls back
	 * to a locking build if the edition doesn't support ONLINE index creation.
	 *
	 * We use EXEC() in the online path so the error severity is lowered enough for the CATCH block to catch it.
	 */
	@Nonnull
	static String buildOnlineCreateWithTryCatchFallback(String theBareCreateSql) {
		return "BEGIN TRY -- try first online, without locking the table \n"
				+ "    EXEC('" + theBareCreateSql + " WITH (ONLINE = ON)');\n"
				+ "END TRY \n"
				+ "BEGIN CATCH -- for Editions of Sql Server that don't support ONLINE, run with table locks \n"
				+ theBareCreateSql + "; \n"
				+ "END CATCH;";
