			// Drop index
			switch (driverType) {
				case MYSQL_5_7:
				case MARIADB_10_1:
					sql.add("alter table " + getTableName() + " drop index " + myIndexName);
					break;
				case POSTGRES_9_4:
					sql.add("drop index " + (myOnline ? "CONCURRENTLY " : "") + myIndexName);
					setTransactional(!myOnline);
					break;
				case DERBY_EMBEDDED:
				case H2_EMBEDDED:
					sql.add("drop index " + myIndexName);
					break;
				case ORACLE_12C:
